parameters.checklist:
[
  {
    "id": "context-is-substantive",
    "assert": "the context note carries at least 150 words",
    "cmd": "test \"$(wc -w < ${notes_dir}/01-context.md)\" -ge 150",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "context-names-real-files",
    "assert": "the context note names at least three paths that exist in the repository",
    "cmd": "test \"$(grep -oE '[A-Za-z0-9_.-]+(/[A-Za-z0-9_.-]+)+' ${notes_dir}/01-context.md | sort -u | while read -r p; do test -e \"$p\" && echo \"$p\"; done | wc -l)\" -ge 3",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "context-is-grounded",
    "context": [
      "${notes_dir}/01-context.md"
    ],
    "judge": "Does this note describe the actual code the feature touches — its entry points, the functions involved, the existing patterns and the tests that cover it? FAIL if it is generic enough to fit any codebase or names things that are not in the repository.",
    "blocking": true,
    "origin": "pe-profile:feature-launch@1.0.0"
  }
]

[
  {
    "id": "spec-is-substantive",
    "assert": "the spec carries at least 150 words",
    "cmd": "test \"$(wc -w < ${notes_dir}/02-spec.md)\" -ge 150",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "criteria-are-testable",
    "context": [
      "${notes_dir}/01-context.md",
      "${notes_dir}/02-spec.md"
    ],
    "judge": "Is every acceptance criterion in this spec observable and testable, and do the criteria together cover the goal? FAIL if a criterion is vague (\"works well\", \"is fast\"), describes implementation instead of behaviour, or if part of the goal has no criterion.",
    "blocking": true,
    "origin": "pe-profile:feature-launch@1.0.0"
  }
]

[
  {
    "id": "review-is-substantive",
    "assert": "the spec review carries at least 100 words",
    "cmd": "test \"$(wc -w < ${notes_dir}/02-spec-review.md)\" -ge 100",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "findings-are-resolved",
    "context": [
      "${notes_dir}/02-spec.md",
      "${notes_dir}/02-spec-review.md"
    ],
    "judge": "Does this review raise at least two concrete findings about the spec, and does the spec now resolve each one or record it under Open questions with a reason? FAIL if the review only praises the spec, if its findings are generic, or if a finding is neither resolved nor recorded.",
    "blocking": true,
    "origin": "pe-profile:feature-launch@1.0.0"
  }
]

[
  {
    "id": "spec_has_sections",
    "assert": "spec_has_sections",
    "cmd": "for section in Goal \"Acceptance criteria\" \"Out of scope\" Risks \"Open questions\"; do grep -q \"^## $section\" ${notes_dir}/02-spec.md || { echo \"missing $section\"; exit 1; }; done",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "criteria_numbered",
    "assert": "criteria_numbered",
    "cmd": "test \"$(grep -cE '^AC[0-9]+:' ${notes_dir}/02-spec.md)\" -ge 3",
    "origin": "pe-profile:feature-launch@1.0.0"
  }
]

[
  {
    "id": "plan-has-rollback",
    "assert": "the plan ends with a Rollback section",
    "cmd": "grep -q '^## Rollback' ${notes_dir}/03-plan.md",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "every-criterion-planned",
    "assert": "every acceptance criterion from the spec is delivered by a slice",
    "cmd": "ids=$(grep -oE '^AC[0-9]+' ${notes_dir}/02-spec.md) || exit 1; for id in $ids; do grep -qw \"$id\" ${notes_dir}/03-plan.md || { echo \"$id is in no slice\"; exit 1; }; done",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "slices-are-reviewable",
    "context": [
      "${notes_dir}/02-spec.md",
      "${notes_dir}/03-plan.md"
    ],
    "judge": "Is each slice small enough to review on its own, does it name real files, and does the order put risky or foundational work first? FAIL if a slice bundles unrelated changes, leaves the code broken, or names no files.",
    "blocking": true,
    "origin": "pe-profile:feature-launch@1.0.0"
  }
]

[
  {
    "id": "tests-added",
    "assert": "tests were added or changed",
    "cmd": "git diff --name-only ${base_ref} -- ${test_path} | grep -q . || git ls-files --others --exclude-standard -- ${test_path} | grep -q .",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "suite-is-red",
    "assert": "the suite fails because the feature is missing",
    "cmd": "! ${test_cmd}",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "every-criterion-has-a-test",
    "assert": "every acceptance criterion id appears in the tests",
    "cmd": "ids=$(grep -oE '^AC[0-9]+' ${notes_dir}/02-spec.md) || exit 1; for id in $ids; do grep -rqw \"$id\" ${test_path} || { echo \"$id has no test\"; exit 1; }; done",
    "origin": "pe-profile:feature-launch@1.0.0"
  }
]

[
  {
    "id": "source-changed",
    "assert": "the source paths were changed",
    "cmd": "git diff --name-only ${base_ref} -- ${src_path} | grep -q . || git ls-files --others --exclude-standard -- ${src_path} | grep -q .",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "suite-is-green",
    "assert": "the suite passes",
    "cmd": "${test_cmd}",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "no-test-deleted",
    "assert": "no test file was deleted to get to green",
    "cmd": "! git diff --diff-filter=D --name-only ${base_ref} -- ${test_path} | grep -q .",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "implements-the-plan",
    "context": [
      "${notes_dir}/03-plan.md"
    ],
    "judge": "Does this change implement the plan's slices using the patterns the code already has? FAIL if it special-cases test inputs, weakens or skips a test, or adds behaviour the spec does not ask for.",
    "diff": true,
    "blocking": true,
    "origin": "pe-profile:feature-launch@1.0.0"
  }
]

[
  {
    "id": "suite-green-with-edges",
    "assert": "the suite passes with the edge-case tests",
    "cmd": "${test_cmd}",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "risks-are-tested",
    "context": [
      "${notes_dir}/02-spec.md"
    ],
    "judge": "Does this change add tests for the edge cases and failure modes the spec's Risks section names, and fix the code where they failed? FAIL if a named risk has no test, or if the tests only repeat the happy path.",
    "diff": true,
    "blocking": true,
    "origin": "pe-profile:feature-launch@1.0.0"
  }
]

[
  {
    "id": "suite_green",
    "assert": "suite_green",
    "cmd": "${test_cmd}",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "lint_clean",
    "assert": "lint_clean",
    "cmd": "${lint_cmd}",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "criteria_tested",
    "assert": "criteria_tested",
    "cmd": "ids=$(grep -oE '^AC[0-9]+' ${notes_dir}/02-spec.md) || exit 1; for id in $ids; do grep -rqw \"$id\" ${test_path} || { echo \"$id has no test\"; exit 1; }; done",
    "origin": "pe-profile:feature-launch@1.0.0"
  }
]

[
  {
    "id": "suite-green-after-simplify",
    "assert": "the suite still passes",
    "cmd": "${test_cmd}",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "lint-clean-after-simplify",
    "assert": "the linter passes",
    "cmd": "${lint_cmd}",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "behaviour-unchanged",
    "judge": "Does this change only simplify the code — removing duplication and dead code, improving names, splitting long functions — without changing behaviour? FAIL if it changes a test's expectations, a public signature or an output, or adds a feature.",
    "diff": true,
    "blocking": true,
    "origin": "pe-profile:feature-launch@1.0.0"
  }
]

[
  {
    "id": "docs-changed",
    "assert": "the documentation paths were changed",
    "cmd": "git diff --name-only ${base_ref} -- ${docs_path} | grep -q . || git ls-files --others --exclude-standard -- ${docs_path} | grep -q .",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "docs-teach-the-feature",
    "context": [
      "${notes_dir}/02-spec.md"
    ],
    "judge": "Would a user who reads only this documentation change know what the feature does, how to use it and what its limits are? FAIL if it describes the implementation instead of the use, contradicts the spec, or leaves a user-visible behaviour undocumented.",
    "diff": true,
    "blocking": true,
    "origin": "pe-profile:feature-launch@1.0.0"
  }
]

[
  {
    "id": "every-criterion-reviewed",
    "assert": "the review names every acceptance criterion id",
    "cmd": "ids=$(grep -oE '^AC[0-9]+' ${notes_dir}/02-spec.md) || exit 1; for id in $ids; do grep -qw \"$id\" ${notes_dir}/06-review.md || { echo \"$id is not reviewed\"; exit 1; }; done",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "final-review-is-substantive",
    "assert": "the review carries at least 120 words",
    "cmd": "test \"$(wc -w < ${notes_dir}/06-review.md)\" -ge 120",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "review-shows-evidence",
    "context": [
      "${notes_dir}/02-spec.md",
      "${notes_dir}/06-review.md"
    ],
    "judge": "Does this review back every acceptance criterion with a named test, and report defects or risks specifically enough to act on? FAIL if a criterion is marked met without evidence, if a finding is generic, or if it claims something the code does not show.",
    "blocking": true,
    "origin": "pe-profile:feature-launch@1.0.0"
  }
]

[
  {
    "id": "conventional-title",
    "assert": "the description starts with a conventional commit title",
    "cmd": "head -n 1 ${notes_dir}/07-pull-request.md | grep -qE '^(feat|fix|docs|chore|refactor|test|perf)(\\([a-z0-9-]+\\))?!?: .+'",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "description-has-its-sections",
    "assert": "the description has Summary, Testing and Risk and rollback sections",
    "cmd": "for section in Summary Testing \"Risk and rollback\"; do grep -q \"^## $section\" ${notes_dir}/07-pull-request.md || { echo \"missing $section\"; exit 1; }; done",
    "origin": "pe-profile:feature-launch@1.0.0"
  },
  {
    "id": "description-is-reviewable",
    "context": [
      "${notes_dir}/02-spec.md",
      "${notes_dir}/07-pull-request.md"
    ],
    "judge": "Could a reviewer understand what this change does, why, how it was tested and how to roll it back from this description alone? FAIL if it is vague, if it omits the testing that was run, or if it contradicts the spec.",
    "blocking": true,
    "origin": "pe-profile:feature-launch@1.0.0"
  }
]
